def F(no, ja, sel, kind, trig="view", **kw):
    d = {"no": no, "ja": ja, "vi": "", "sel": sel, "kind": kind, "trig": trig}
    for k, v in kw.items():
        if v is None:
            continue
        if k in PAIR and isinstance(v, str):
            v = [v, ""]
        if k == "ex" and isinstance(v, str):
            v = [v, ""]
        if k == "len" and isinstance(v, str):
            v = [v, ""]
        d[k] = v
    return d


def X(no, ja, d=None, sel="-", kind="label", trig="view", cond=None, demo=None, **kw):
    """状態で足す項目（detail・cond・demo_ok は日本語の文字列）"""
    if d:
        kw["detail"] = d
    if cond:
        kw["cond"] = cond
    if demo:
        kw["demo_ok"] = demo
    return F(no, ja, sel, kind, trig, **kw)


def ST(vid, code, state, note, items, url, **kw):
    d = {"id": vid, "code": code, "state": [state, ""], "url": url, "setup": kw.pop("setup", ""), "full": kw.pop("full", False), "wait": kw.pop("wait", 600),
         "note": [note, ""], "items": items}
    d.update(kw)
    return d


