# ================================================================ AW_CONT_002 詳細・AW_CONT_003 編集の共通部分
def D_HEADER(edit=False):
    kind = "子契約編集" if edit else "子契約詳細"
    out = [
        F("1", "ヘッダー", ".phead", "area", pattern="P-FORM" if edit else None,
          detail=("固定するのは1行（画面名・ID・キャンセル・保存）だけ。要約・タブ・「保存できません（n件）」の枠は画面を送ると流れる。保存のボタンが長いフォームで隠れない（台帳 F 再レビュー(4)・P-FORM）。" if edit else None),
          demo_ok=("コードは見出しを固定しない（宿題）。仕様は P-FORM（台帳 F 再レビュー(4)）" if edit else None)),
        F("1.1", "パンくず", ".crumb", "label", detail="「法人・契約管理 / 子契約一覧 / %s」。2つ目のリンクは一覧へ戻る。来た画面がある（?from= があるとき）は「前の画面」と表示し、その画面へ戻る（Q-C8・状態 035）。編集中なら Q02。" % kind),
        F("1.2", "画面名", ".phead h2", "label", detail="「%s」＋子契約ID。" % kind),
        F("1.3", "拠点のリンク", ".idlinks span::拠点", "link", "click",
          detail="見出しの下に「拠点 CU…」のリンクを出す。押すとその拠点の画面（AW_BRCH_002・/ops/branches/<拠点ID>）へ移る（編集中なら Q02）。"),
        F("1.4", "親契約のリンク", ".idlinks span::親契約", "link", "click",
          detail="「親契約 CP…」のリンク。押すとその拠点の「契約」タブ（AW_BRCH_002 の ?tab=契約）へ移る。親契約専用の画面は作らない（/ops/contracts/parents/[no] は画面コードを付けず、設計書に載せない・Q-C5）。"),
        F("1.5", "法人のリンク", ".idlinks span::法人", "link", "click",
          detail="「法人 CU…」のリンク。押すと所属法人の画面（AW_CORP_002・/ops/corps/<法人ID>）へ移る。"),
    ]
    if edit:
        out += [
            F("1.6", "キャンセル", ".pbtn button.cancel", "button", "click", err=["Q02"], detail="入力を変えていれば Q02（キャンセル／破棄）。詳細から来たときは詳細へ、一覧から来たときは一覧へ戻る（来た画面へ戻る＝Q-C8）。"),
            F("1.7", "保存", ".pbtn button.save", "button", "click", err=["S01", "S13", "E30", "E31", "E32", "I02", "Q12", "E54"],
              detail="全タブの全項目をまとめてチェックして保存する。この子契約より後に生成済みの子契約があるときだけ、適用範囲のダイアログ（Q12・状態 021）を出す。保存できたら S01（後ろの子契約がなく確認なし）か S13（のみ／以降すべて）を出して詳細へ。ボタンは押したら無効にする。保存のときの通信エラーは E30、権限がないときは E32。ほかの人が先に保存していれば E31＝上書き警告のモーダル。承認待ちの変更申請がある項目は直接編集を止める（I102）。確定・請求済の子契約でも、契約変更の受付の締切（そのサイクル月のオーダー締切）までは金額に効く項目を直せる。締切を過ぎると金額に効く変更はできない（E54）。",
              ),
        ]
    else:
        out += [
            F("1.6", "編集", ".pbtn button.save", "button", "click", cond=CAN_U,
              detail="編集（AW_CONT_003）へ。削除のボタンは置かない（運営A Q1）。仮登録の子契約は出さない（「申請詳細で編集」を出す）。取消の子契約も出さない（I15）。"),
        ]
    return out


