def TOOLS(edit=False):
    out = [
        F("4", "項目の検索", ".tools", "area", pattern="P-DETAIL-AUX", detail="項目名・値・説明を絞り込む。タブの下に、カードごとの項目数つきの目次を出す（共通パターン P-DETAIL-AUX）。"),
        F("4.1", "項目を検索", ".tools .srch input", "text", "input", req="－", len="文字列 60", init="空", ex="配送",
          detail="「/」は、どの入力欄にもフォーカスがないときだけ検索欄へ移る（備考などに「/」を入力できる）。Esc で検索を消す。0件のときは I01 を出す。", err=["I01"]),
        F("4.2", "すべて閉じる・開く", ".tools button::すべて", "button", "click", detail="そのタブのカードをすべて閉じる／開く。ボタンの名前が入れ替わる。"),
    ]
    if not edit:
        out.append(F("4.3", "編集できる項目だけ", ".tools label::編集できる項目だけ", "check", "check", req="－", len="チェック", init="OFF", ex="ON",
                     detail="編集のボタンがある詳細（仮登録・取消の子契約・編集の権限がない役割の詳細には編集のボタンがないので出さない）にだけ出す。ON にすると、編集できない項目（承認待ちで止めた項目を含む）を隠す。空になったカードは隠す。同じ画面を開いているあいだは覚え、開き直すと OFF に戻る。"))
    return out


def card(no, title, ja=None, **kw):
    return F(no, ja or title, ".ch::%s^" % title, "area", **kw)


