def route_items(edit):
    out = [card("9", "配送ルート設定（テーブル）",
                detail="配送種別ごとのルート（倉庫・運送会社・納品会社・中継・リードタイム・回数・パターン・サイクル）の表。直送＝倉庫で受け取って拠点へそのまま届ける（途中経由「なし」・運送会社と納品会社が同じ）。中継＝倉庫→（運送会社）→中継先→（納品会社）→拠点。委託＝委託配送会社のドライバーが運ぶ。" + ("行を追加・削除できる。" if edit else "表示だけ。"),
                err=["I102"] if edit else None)]
    for (n, ja, k, ln, ex, dt) in ROUTE_COLS:
        sel = "table th::%s" % ja if ja != "配送種別" else "th::配送種別"
        if not edit or k == "label":
            out.append(F(n, ja, sel, "label", detail=dt))
        else:
            kw = dict(req="○" if ja in ("配送種別", "ピッキング倉庫", "運送会社", "納品会社", "途中経由1", "リードタイム", "配送回数", "配送パターン") else "－", len=ln, init="保存済みの値", ex=ex, detail=dt)
            if ja == "問い合わせ確認URL":
                kw["err"] = ["E10", "E04"]
            elif k == "text":
                kw["err"] = ["E01", "E12", "E14"] if kw["req"] == "○" else ["E12", "E14"]
            else:
                kw["err"] = ["E02"]
            out.append(F(n, ja, sel, k, "select" if k == "select" else "input", **kw))
    if edit:
        out += [F("9.12", "行を追加", ".card button::行を追加", "button", "click", detail="空の行を1行足す。配送種別ごとに1行。"),
                F("9.13", "行の削除", ".card .del", "button", "click", detail="その行を消す（ゴミ箱）。")]
    return out


def slot_items(edit):
    out = [card("10", "回ごとのルート（この回だけ変える）",
                detail="その回だけ、上の行（配送種別ごとの標準のルート）と違うピッキング倉庫・運送会社・納品会社・中継先で運ぶための表。回は上の行の納品サイクルから選ぶ。入れない回は上の行のルート。配送ルートの一括変更はこの回を変えない（配送_03）。" + ("" if edit else "表示だけ。"))]
    out.append(F("10.1", "回（納品サイクル）", "th::回（納品サイクル）", "select" if edit else "label", "select" if edit else "view",
                 **(dict(req="○", len="選択（A1〜D7）", init="保存済みの値", ex="A1", err=["E02"], detail="どの回だけ変えるか。上の行の納品サイクルから選ぶ。") if edit else dict(detail="どの回だけ変えるか。"))))
    out.append(F("10.2", "回ごとの配送種別・倉庫・運送会社・納品会社・途中経由1", "-", "label",
                 detail="列の決まりは上の表（9.1・9.2・9.3・9.4・9.5）と同じ。配送種別は冷蔵配送・冷凍配送だけ選べる。"))
    if edit:
        out += [F("10.3", "行を追加（回ごと）", ".card button::行を追加^", "button", "click", detail="空の行を1行足す。"),
                F("10.4", "行の削除（回ごと）", "-", "button", "click", detail="その行を消す（ゴミ箱）。")]
    return out


