def spec_sel(f):
    return f.get("sel") or fsel(f["ja"])


def view_item(f):
    kind = "button" if f["kind"] == "btn" else "label"
    kw = {}
    if f["kind"] in ("label", "btn") or f.get("ro"):
        kw["detail"] = f["d"]
    else:
        kw["detail"] = "表示だけ。" + f["d"]
        COMPOSE[kw["detail"]] = ["表示だけ。", f["d"]]
    if f["kind"] == "btn":
        for k in ("err", "cond"):
            if f.get(k):
                kw[k] = f[k]
    if f.get("open"):
        kw["open"], kw["ask"] = f["open"], f.get("ask", "hong")
    if f.get("ok"):
        kw["demo_ok"] = f["ok"]
    return F(f["no"], f["ja"], spec_sel(f), kind, "click" if kind == "button" else "view", **kw)


def edit_item(f):
    k = f["kind"]
    if f.get("ro") or k == "label":
        return F(f["no"], f["ja"], spec_sel(f), "label", detail=f.get("d", "") or "入力できない（表示だけ）。", **({"demo_ok": f["ok"]} if f.get("ok") else {}))
    if k == "btn":
        return view_item(f)
    kw = {"ex": f.get("ex", ""), "init": f.get("init", "保存済みの値")}
    for a, b in (("req", "req"), ("len", "len"), ("d", "detail"), ("v", "valid"), ("cond", "cond"), ("ok", "demo_ok"), ("open", "open"), ("ask", "ask"), ("err", "err")):
        if f.get(a):
            kw[b] = f[a]
    if f.get("open") and not kw.get("ask"):
        kw["ask"] = "hong"
    trig = {"text": "input", "textarea": "input", "select": "select", "date": "input", "month": "input", "check": "check"}.get(k, "input")
    return F(f["no"], f["ja"], spec_sel(f), k, trig, **kw)


def grp(no, title, key, edit, detail=None, skip=()):
    return [card(no, title, detail=detail)] + [(edit_item if edit else view_item)(f) for f in CF[key] if f["no"] not in skip]


def tab_contract(edit):
    return (grp("5", "子契約", "contract", edit, "この子契約（月次）の識別と範囲。", skip=tuple(f["no"] for f in CF["contract"] if f["no"].startswith("6.")))
            + grp("6", "契約", "contract", edit, "プラン・コース・期間・価格世代。承認待ちの変更申請の対象の項目は直接編集を止める。", skip=tuple(f["no"] for f in CF["contract"] if f["no"].startswith("5.")))
            + grp("7", "アプリの利用設定（このサイクル月）", "app", edit, "持ち主は子契約。法人Webの拠点の「編集」で直すと、今のサイクル以降のすべての子契約に効く（運営は保存のときに「この子契約だけ」も選べる）。")
            + grp("8", "配送・納品スケジュール", "ship", edit)
            + route_items(edit) + slot_items(edit)
            + grp("11", "メモ", "memo", edit))


