# ================================================================ AW_CONT_005 子契約CSV取込（P-CSV・2ステップ）
# 列の定義は画面に出さず、項目定義に入力項目と同じ形で書く（sel＝"-"・台帳 F）。列は子契約一覧の CSV出力と同じ（1行目の見出し・この順）。キー＝子契約ID（更新だけ）。
CSV_INIT = "空欄（今の値のまま）"
CSV_BLANK = {"○": "必須の項目。空欄は今の値のまま。「-」で消すことはできない（E01）。",
             "－": "空欄は今の値のまま。「-」で消せる。",
             "条件付き": "空欄は今の値のまま。条件に当てはまるときは必須で、「-」で消すことはできない。"}


def csv_col(no, f, ja=None, ex=None, extra=None, err_add=(), ok=None, clear=True):
    """画面の入力項目 f の CSV 列（定義だけ・sel＝"-"）"""
    ja = ja or f["ja"]
    req = f.get("req", "－")
    parts = [CSV_BLANK[req] if clear or req != "－" else "空欄は今の値のまま（この列は消せない）。"]
    if f.get("v"):
        parts.append(f["v"])
    if extra:
        parts.append(extra)
    valid = "".join(parts)
    if len(parts) > 1:
        COMPOSE[valid] = parts
    detail = "画面の項目 %s「%s」と同じ。" % (f["no"], f["ja"])
    kw = dict(req=("条件付き" if req == "条件付き" else "－"), len=f.get("len"), valid=valid, detail=detail, ex=ex or f.get("ex", ""), init=CSV_INIT)
    if f.get("cond"):
        kw["cond"] = f["cond"]
    _err = list(f.get("err") or [])
    if req == "○" and "E01" not in _err:
        _err.insert(0, "E01")
    _err += list(err_add)
    _err = [e for e in _err if e not in ("I102",)]
    if _err:
        kw["err"] = _err
    if ok or f.get("ok"):
        kw["demo_ok"] = ok or f.get("ok")
    k = f["kind"] if f["kind"] in ("text", "textarea", "select", "month", "date") else "text"
    return F(no, ja, "-", k, "input", **kw)


def _cf(no):
    for v in CF.values():
        for f in v:
            if f["no"] == no:
                return f
    raise KeyError(no)


